// Synthetic normal-Save + actual public-publisher bytes. No credentials/operational data.
import fs from'node:fs';import vm from'node:vm';import assert from'node:assert/strict';import{webcrypto,createHash}from'node:crypto';
import{clock,response,SECRET,eventLoop}from'./serving_public_io_cases.mjs';
export{clock,response,SECRET,eventLoop};export const M=1024*1024,BASE='https://kennedyjasondavid-eng.github.io/conc-recipe-hub/',P=BASE+'pages_provenance.json',D=BASE+'DOOR_RECIPE_DATA.json',L=BASE+'library_public.json',plain=x=>JSON.parse(JSON.stringify(x)),clone=structuredClone,bytes=s=>new TextEncoder().encode(s),canonical=x=>x===null||typeof x!=='object'?JSON.stringify(x):Array.isArray(x)?'['+x.map(canonical).join(',')+']':'{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}',sha=x=>createHash('sha256').update(x).digest('hex');
const fixtureRoot=new URL('./serving_catalogue/public/',import.meta.url);export function fixture(){return{provenanceBytes:new Uint8Array(fs.readFileSync(new URL('pages_provenance.json',fixtureRoot))),primaryFeedBytes:new Uint8Array(fs.readFileSync(new URL('DOOR_RECIPE_DATA.json',fixtureRoot))),libraryBytes:new Uint8Array(fs.readFileSync(new URL('library_public.json',fixtureRoot)))}}
export function changed(f,change){const p=JSON.parse(new TextDecoder().decode(f.provenanceBytes)),base=JSON.parse(new TextDecoder().decode(f.primaryFeedBytes)),library=JSON.parse(new TextDecoder().decode(f.libraryBytes));change({p,base,library});library._meta.count=library.recipes.filter(r=>!r.removed).length;const primaryFeedBytes=bytes(JSON.stringify(base)),libraryBytes=bytes(JSON.stringify(library));p.primaryFeed.sha256=sha(primaryFeedBytes);p.sharedLibrary.sha256=sha(libraryBytes);return{provenanceBytes:bytes(JSON.stringify(p)),primaryFeedBytes,libraryBytes}}
export function descriptor(f){const p=JSON.parse(new TextDecoder().decode(f.provenanceBytes));return{schema:1,main:p.sources.main,sharedLibrary:p.sources.sharedLibrary,doorRecipeDataSha256:p.primaryFeed.sha256,libraryPublicSha256:p.sharedLibrary.sha256}}
export function core(crypto=webcrypto){const html=fs.readFileSync(process.env.SERVING_CATALOGUE_HTML||new URL('../../index.html',import.meta.url),'utf8');let s='';for(const n of['flow-validity','serving-catalogue-v1']){const a=html.indexOf('/* HOUSE_TESTABLE_CORE_START '+n+' */'),z=html.indexOf('/* HOUSE_TESTABLE_CORE_END '+n+' */',a);assert.ok(a>=0&&z>a,'actual portable '+n+' region exists');s+=html.slice(a,z)+'\n'}const ambient=[],no=()=>{ambient.push(true);throw Error(SECRET)};const c=vm.createContext({crypto,TextEncoder,TextDecoder,Uint8Array,URL,Headers,console:{log:no,warn:no,error:no},fetch:no,AbortController:class{constructor(){no()}},setTimeout:no,clearTimeout:no,localStorage:{getItem:no,setItem:no}});vm.runInContext(s,c);for(const n of['houseServingV1CatalogueFromPublic','houseServingV1CatalogueIOCreate'])assert.equal(typeof c[n],'function',n);return{c,ambient}}
export async function parse(f=fixture(),crypto){const{c,ambient}=core(crypto),r=await c.houseServingV1CatalogueFromPublic(f);assert.deepEqual(ambient,[]);return r}
export function goodResult(r){assert.equal(r.ok,true);assert.deepEqual(Object.keys(r).sort(),['catalogue','ok']);assert.deepEqual(Object.keys(r.catalogue).sort(),['descriptor','displayRecipes','issues','recipes','revision','schema']);return r.catalogue}
export function failure(r,reason){assert.equal(r.ok,false);assert.deepEqual(Object.keys(r).sort(),['ok','reason']);if(reason)assert.equal(r.reason,reason);assert.ok(!JSON.stringify(r).includes(SECRET));return r}
export function setup(fetcher,crypto){const{c,ambient}=core(crypto),timers=clock(),calls=[],controllers=[];class Controller extends AbortController{constructor(){super();controllers.push(this)}}const caps={fetch:(url,init)=>{calls.push({url,init});return fetcher(url,init,calls.length)},AbortController:Controller,setTimeout:timers.setTimeout.bind(timers),clearTimeout:timers.clearTimeout.bind(timers)};const r=c.houseServingV1CatalogueIOCreate({site:'rexdale'},caps);assert.equal(r.ok,true);assert.deepEqual(Object.keys(r.io),['fetchCatalogue']);return{...r,c,ambient,timers,calls,controllers,caps}}
export function good(f=fixture(),second=f.provenanceBytes){const replies=[],payload=[f.provenanceBytes,f.primaryFeedBytes,f.libraryBytes,second];return{replies,fetcher:async(url,init,n)=>{const r=response(url,[payload[n-1]],{headers:{'content-type':'application/json; charset=utf-8'}});replies.push(r);return r.value}}}
export function overlay(f){const html=fs.readFileSync(new URL('../../index.html',import.meta.url),'utf8'),a=html.indexOf('/* DOOR_TESTABLE_CORE_START shared-recipes */'),z=html.indexOf('/* DOOR_TESTABLE_CORE_END shared-recipes */',a),c=vm.createContext({});assert.ok(a>=0&&z>a);vm.runInContext(html.slice(a,z),c);return plain(c.doorOverlaySharedRecipes(JSON.parse(new TextDecoder().decode(f.primaryFeedBytes)),JSON.parse(new TextDecoder().decode(f.libraryBytes))).list)}
export function first(r){return goodResult(r).recipes.find(x=>x.recipeId==='technical-fixture-written-yield')}
